import{_t as e,it as t,n,rt as r}from"./chunks/framework.BJB2RXm-.js";var i=JSON.parse(`{"title":"Frequently asked questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently asked questions”">​</a></h1><p>Common questions about setting up, developing, testing, and contributing to the BCEW monorepo.</p><h2 id="setup-and-dependencies" tabindex="-1">Setup and dependencies <a class="header-anchor" href="#setup-and-dependencies" aria-label="Permalink to “Setup and dependencies”">​</a></h2><h3 id="why-does-pnpm-install-fail-with-err-pnpm-unsupported-engine" tabindex="-1">Why does <code>pnpm install</code> fail with <code>ERR_PNPM_UNSUPPORTED_ENGINE</code>? <a class="header-anchor" href="#why-does-pnpm-install-fail-with-err-pnpm-unsupported-engine" aria-label="Permalink to “Why does pnpm install fail with ERR_PNPM_UNSUPPORTED_ENGINE?”">​</a></h3><p>The repository enforces its required Node.js version.</p><p>Check <code>engines.node</code> in the root <code>package.json</code> and install a compatible Node.js version before running:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h3 id="what-should-i-do-if-pnpm-install-fails" tabindex="-1">What should I do if <code>pnpm install</code> fails? <a class="header-anchor" href="#what-should-i-do-if-pnpm-install-fails" aria-label="Permalink to “What should I do if pnpm install fails?”">​</a></h3><p>Run installation commands from the monorepo root and confirm that your Node.js version matches the version required by <code>package.json</code>.</p><p>If you need a clean reinstall while keeping the existing dependency resolution:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store path)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span></code></pre></div><p>Keep <code>pnpm-lock.yaml</code> unless you intentionally need to change dependency resolution.</p><h3 id="where-is-the-pnpm-store" tabindex="-1">Where is the pnpm store? <a class="header-anchor" href="#where-is-the-pnpm-store" aria-label="Permalink to “Where is the pnpm store?”">​</a></h3><p>Check the store used by your current environment:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span></code></pre></div><p>A <code>.pnpm-store</code> directory in the repository does not mean pnpm is using it. The active store is controlled by pnpm configuration.</p><h3 id="why-do-i-get-module-not-found-after-adding-an-import" tabindex="-1">Why do I get <code>Module not found</code> after adding an import? <a class="header-anchor" href="#why-do-i-get-module-not-found-after-adding-an-import" aria-label="Permalink to “Why do I get Module not found after adding an import?”">​</a></h3><p>Add the dependency to the <code>package.json</code> for the package that uses it, then run:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>from the monorepo root.</p><h3 id="how-should-i-handle-the-wrong-version-of-a-transitive-dependency" tabindex="-1">How should I handle the wrong version of a transitive dependency? <a class="header-anchor" href="#how-should-i-handle-the-wrong-version-of-a-transitive-dependency" aria-label="Permalink to “How should I handle the wrong version of a transitive dependency?”">​</a></h3><p>Add the required dependency directly to the package that needs it.</p><p>Root pnpm overrides can be used when a dependency must be controlled across the workspace. Coordinate workspace-wide overrides with the team.</p><h3 id="how-should-i-handle-peer-dependency-warnings" tabindex="-1">How should I handle peer dependency warnings? <a class="header-anchor" href="#how-should-i-handle-peer-dependency-warnings" aria-label="Permalink to “How should I handle peer dependency warnings?”">​</a></h3><p>Install the required peer dependency in the package that consumes it and keep shared dependency versions aligned across the workspace.</p><h3 id="how-do-i-resolve-duplicate-react-or-wordpress-package-issues" tabindex="-1">How do I resolve duplicate React or WordPress package issues? <a class="header-anchor" href="#how-do-i-resolve-duplicate-react-or-wordpress-package-issues" aria-label="Permalink to “How do I resolve duplicate React or WordPress package issues?”">​</a></h3><p>Check the root and package <code>package.json</code> files and keep shared <code>@wordpress/*</code> dependencies aligned across the workspace.</p><h3 id="what-should-i-check-when-composer-install-fails" tabindex="-1">What should I check when <code>composer install</code> fails? <a class="header-anchor" href="#what-should-i-check-when-composer-install-fails" aria-label="Permalink to “What should I check when composer install fails?”">​</a></h3><p>Confirm that your local PHP environment provides the PHP extensions required by <code>composer.json</code>.</p><p>For Composer path repositories, verify that the configured <code>url</code> is correct relative to the <code>composer.json</code> that defines it.</p><h2 id="local-wordpress-environments" tabindex="-1">Local WordPress environments <a class="header-anchor" href="#local-wordpress-environments" aria-label="Permalink to “Local WordPress environments”">​</a></h2><h3 id="what-should-i-do-when-a-wp-env-port-is-already-allocated" tabindex="-1">What should I do when a wp-env port is already allocated? <a class="header-anchor" href="#what-should-i-do-when-a-wp-env-port-is-already-allocated" aria-label="Permalink to “What should I do when a wp-env port is already allocated?”">​</a></h3><p>Another WordPress environment may already be running.</p><p>From the monorepo root, stop running environments with:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp-env-stop</span></span></code></pre></div><p>If required, configure a different port for the project&#39;s local environment.</p><h3 id="how-can-i-override-wp-env-settings-locally" tabindex="-1">How can I override wp-env settings locally? <a class="header-anchor" href="#how-can-i-override-wp-env-settings-locally" aria-label="Permalink to “How can I override wp-env settings locally?”">​</a></h3><p>Use:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.wp-env.override.json</span></span></code></pre></div><p>alongside the project&#39;s <code>.wp-env.json</code>.</p><p>Use the override for machine-specific settings that should not change the shared project configuration.</p><h2 id="building-and-testing" tabindex="-1">Building and testing <a class="header-anchor" href="#building-and-testing" aria-label="Permalink to “Building and testing”">​</a></h2><h3 id="why-do-i-need-to-rebuild-after-checking-out-another-branch" tabindex="-1">Why do I need to rebuild after checking out another branch? <a class="header-anchor" href="#why-do-i-need-to-rebuild-after-checking-out-another-branch" aria-label="Permalink to “Why do I need to rebuild after checking out another branch?”">​</a></h3><p>Build output is not committed to the repository. After switching to or updating a branch, refresh dependencies and rebuild so generated files match that branch:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="how-do-i-build-only-one-project" tabindex="-1">How do I build only one project? <a class="header-anchor" href="#how-do-i-build-only-one-project" aria-label="Permalink to “How do I build only one project?”">​</a></h3><p>From the monorepo root:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">project-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:build</span></span></code></pre></div><h3 id="why-does-ci-run-tests-for-projects-i-did-not-directly-change" tabindex="-1">Why does CI run tests for projects I did not directly change? <a class="header-anchor" href="#why-does-ci-run-tests-for-projects-i-did-not-directly-change" aria-label="Permalink to “Why does CI run tests for projects I did not directly change?”">​</a></h3><p>Nx determines affected projects from both changed files and the project dependency graph. A change to shared code can therefore affect multiple projects.</p><h3 id="what-tests-run-for-a-pull-request" tabindex="-1">What tests run for a pull request? <a class="header-anchor" href="#what-tests-run-for-a-pull-request" aria-label="Permalink to “What tests run for a pull request?”">​</a></h3><p>The pull request workflow coordinates:</p><ul><li>linting</li><li>JavaScript unit tests</li><li>PHP integration tests</li><li>Playwright end-to-end tests</li><li>accessibility tests</li><li>screenshot tests</li><li>SonarQube analysis</li></ul><p>Applicable test workflows use Nx affected-project detection.</p><h3 id="where-do-i-find-playwright-failure-information" tabindex="-1">Where do I find Playwright failure information? <a class="header-anchor" href="#where-do-i-find-playwright-failure-information" aria-label="Permalink to “Where do I find Playwright failure information?”">​</a></h3><p>Failed Playwright runs upload a project-specific artifact containing available test results, screenshot differences, and traces.</p><p>Check the workflow run in GitHub Actions and download the <code>playwright-report-&lt;project&gt;</code> artifact for the failed project.</p><h2 id="screenshot-testing" tabindex="-1">Screenshot testing <a class="header-anchor" href="#screenshot-testing" aria-label="Permalink to “Screenshot testing”">​</a></h2><h3 id="how-do-i-update-screenshot-baselines" tabindex="-1">How do I update screenshot baselines? <a class="header-anchor" href="#how-do-i-update-screenshot-baselines" aria-label="Permalink to “How do I update screenshot baselines?”">​</a></h3><p>Run the <strong>Run Screenshot Generator</strong> workflow from GitHub Actions and select the project.</p><p>The workflow runs the project&#39;s screenshot-generation target and commits changed snapshots back to the selected branch.</p><p>It does not run against <code>main</code>.</p><h3 id="why-can-t-i-manually-run-a-new-workflow-that-exists-only-on-my-feature-branch" tabindex="-1">Why can&#39;t I manually run a new workflow that exists only on my feature branch? <a class="header-anchor" href="#why-can-t-i-manually-run-a-new-workflow-that-exists-only-on-my-feature-branch" aria-label="Permalink to “Why can&#39;t I manually run a new workflow that exists only on my feature branch?”">​</a></h3><p>A manually dispatched GitHub Actions workflow must first exist on the repository&#39;s default branch.</p><p>Once the workflow exists on <code>main</code>, choose your feature branch when manually running it.</p><h2 id="pull-requests-and-ci" tabindex="-1">Pull requests and CI <a class="header-anchor" href="#pull-requests-and-ci" aria-label="Permalink to “Pull requests and CI”">​</a></h2><h3 id="why-was-a-label-automatically-added-to-my-pull-request" tabindex="-1">Why was a label automatically added to my pull request? <a class="header-anchor" href="#why-was-a-label-automatically-added-to-my-pull-request" aria-label="Permalink to “Why was a label automatically added to my pull request?”">​</a></h3><p>The pull request workflow uses <code>.github/labeler.yml</code> to apply labels based on the files changed.</p><p>Labels identify monorepo, plugin, theme, and project-specific changes.</p><h3 id="what-format-should-my-pull-request-title-use" tabindex="-1">What format should my pull request title use? <a class="header-anchor" href="#what-format-should-my-pull-request-title-use" aria-label="Permalink to “What format should my pull request title use?”">​</a></h3><p>Use Conventional Commits:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type(optional-scope): description</span></span></code></pre></div><p>For example:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat(theme): add event filters</span></span></code></pre></div><p>Supported types are:</p><ul><li><code>feat</code></li><li><code>fix</code></li><li><code>perf</code></li><li><code>revert</code></li><li><code>docs</code></li><li><code>style</code></li><li><code>refactor</code></li><li><code>test</code></li><li><code>build</code></li><li><code>ci</code></li><li><code>chore</code></li></ul><p>Use <code>!</code> before the colon for a breaking change:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat!: description</span></span></code></pre></div><h3 id="why-did-changing-my-pr-title-rerun-validation" tabindex="-1">Why did changing my PR title rerun validation? <a class="header-anchor" href="#why-did-changing-my-pr-title-rerun-validation" aria-label="Permalink to “Why did changing my PR title rerun validation?”">​</a></h3><p>PR title validation is a separate GitHub Actions workflow. Editing the title reruns the title check without requiring the main CI workflow to rerun.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to “Releases”">​</a></h2><h3 id="does-merging-to-main-create-a-release" tabindex="-1">Does merging to <code>main</code> create a release? <a class="header-anchor" href="#does-merging-to-main-create-a-release" aria-label="Permalink to “Does merging to main create a release?”">​</a></h3><p>No. Releases are started manually through the release workflow.</p><h3 id="how-do-i-create-a-release" tabindex="-1">How do I create a release? <a class="header-anchor" href="#how-do-i-create-a-release" aria-label="Permalink to “How do I create a release?”">​</a></h3><p>Run <strong>Create a Release</strong> from GitHub Actions and select:</p><ul><li>the project</li><li>whether the release is an alpha</li><li>an optional version</li></ul><p>If the version is not supplied, Nx determines the release version.</p><h3 id="what-format-do-release-tags-use" tabindex="-1">What format do release tags use? <a class="header-anchor" href="#what-format-do-release-tags-use" aria-label="Permalink to “What format do release tags use?”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;nx-project-name&gt;/v&lt;semver&gt;</span></span></code></pre></div><p>The project portion must match the Nx project name.</p><h3 id="what-does-the-release-workflow-publish" tabindex="-1">What does the release workflow publish? <a class="header-anchor" href="#what-does-the-release-workflow-publish" aria-label="Permalink to “What does the release workflow publish?”">​</a></h3><p>The release workflow:</p><ol><li>Runs Nx Release.</li><li>Creates the release tag and GitHub Release.</li><li>Builds the project release archive.</li><li>Uploads the ZIP to the GitHub Release.</li><li>Updates the Composer <code>packages.json</code>.</li><li>Publishes the Composer repository to GitHub Pages.</li></ol><h3 id="what-happens-if-a-release-tag-is-deleted" tabindex="-1">What happens if a release tag is deleted? <a class="header-anchor" href="#what-happens-if-a-release-tag-is-deleted" aria-label="Permalink to “What happens if a release tag is deleted?”">​</a></h3><p>For a supported release tag, the tag deletion workflow removes its corresponding release metadata from <code>packages.json</code> and republishes the Composer repository.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation”">​</a></h2><h3 id="where-should-package-documentation-go" tabindex="-1">Where should package documentation go? <a class="header-anchor" href="#where-should-package-documentation-go" aria-label="Permalink to “Where should package documentation go?”">​</a></h3><p>Keep documentation with the package it describes:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/&lt;plugin-slug&gt;/docs/</span></span>
<span class="line"><span>themes/&lt;theme-slug&gt;/docs/</span></span></code></pre></div><h3 id="should-i-edit-docs-content" tabindex="-1">Should I edit <code>docs/content/</code>? <a class="header-anchor" href="#should-i-edit-docs-content" aria-label="Permalink to “Should I edit docs/content/?”">​</a></h3><p>No. <code>docs/content/</code> is generated output and is replaced when documentation is synchronized.</p><p>Edit the source documentation under the appropriate plugin or theme instead.</p><h3 id="how-do-i-preview-the-documentation-site" tabindex="-1">How do I preview the documentation site? <a class="header-anchor" href="#how-do-i-preview-the-documentation-site" aria-label="Permalink to “How do I preview the documentation site?”">​</a></h3><p>From the monorepo root:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><h3 id="when-is-the-documentation-site-deployed" tabindex="-1">When is the documentation site deployed? <a class="header-anchor" href="#when-is-the-documentation-site-deployed" aria-label="Permalink to “When is the documentation site deployed?”">​</a></h3><p>Documentation-related pull requests build the site without deploying it.</p><p>Relevant changes merged to <code>main</code> trigger the documentation workflow, which builds and publishes the VitePress site to GitHub Pages.</p><h2 id="getting-more-help" tabindex="-1">Getting more help <a class="header-anchor" href="#getting-more-help" aria-label="Permalink to “Getting more help”">​</a></h2><p>If the problem is reproducible and not covered here, open a GitHub bug report with:</p><ul><li>the affected project or area</li><li>a summary of the problem</li><li>expected and actual behaviour</li><li>steps to reproduce</li><li>relevant environment information</li><li>logs, screenshots, or other supporting information</li></ul>`,111)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};